"""Build subtle terminal chrome and dividers compatible with GitHub image rendering."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'assets'
for filename,label in [('card-top.svg','~/whoami.sh'),('portrait-top.svg','portrait.ascii')]:
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="650" height="42" viewBox="0 0 650 42"><defs><linearGradient id="edge"><stop stop-color="#c4b5e8"/><stop offset=".5" stop-color="#c9d7e8"/><stop offset="1" stop-color="#a3d1d1"/></linearGradient><linearGradient id="wash"><stop stop-color="#9e85ce" stop-opacity=".055"/><stop offset="1" stop-color="#71b8c0" stop-opacity=".035"/></linearGradient></defs><rect x=".7" y=".7" width="648.6" height="38" rx="10" fill="url(#wash)" stroke="url(#edge)"/><path d="M12 2H638" stroke="#fff" stroke-opacity=".65"/><circle cx="18" cy="19" r="3.5" fill="#ed8b97"/><circle cx="31" cy="19" r="3.5" fill="#eac38d"/><circle cx="44" cy="19" r="3.5" fill="#86c5ae"/><text x="325" y="23" text-anchor="middle" font-size="11" font-family="Menlo,Consolas,monospace" fill="#8290a8" letter-spacing="1">{label}</text></svg>'''
 (root/filename).write_text(svg)
(root/'section-divider.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="14" viewBox="0 0 1200 14"><defs><linearGradient id="line"><stop stop-color="#c6bbdf" stop-opacity="0"/><stop offset=".18" stop-color="#b2a2d4" stop-opacity=".65"/><stop offset=".5" stop-color="#99b9d0" stop-opacity=".75"/><stop offset=".82" stop-color="#8fbfc0" stop-opacity=".65"/><stop offset="1" stop-color="#9cc6c9" stop-opacity="0"/></linearGradient></defs><path d="M0 7H1200" stroke="url(#line)"/><rect x="597" y="4" width="6" height="6" rx="1.5" transform="rotate(45 600 7)" fill="#b1afd1"/></svg>''')
